# patch_lifeplus_site_v2.py  （lifeplus-site-v2）
#  ホームページを作り直す（会社のロゴの色・書体・余白で見せる形に）。中身の事実は v1 と同じ
#   ・「3つの入口」の絵はやめて、最初は「からだと、くらしに、プラスを。」とロゴの＋
#   ・ロゴ（docs/img/）を足す
# 何度流しても同じ結果。入れる前の形が違えば何もしないで止まる
import base64, zlib, hashlib, os, shutil, sys
FILES = [
  ("docs/index.html", '64528ea18678c66f35991ad28d8711c8', "8f7f20657acd7197ad01d337892d8291", ""),
  ("docs/dayservice/index.html", 'be3184b6088374e72d1843fa76168400', "98431b97bae8d4b99f4990a4dd382864", ""),
  ("docs/sekkotsu/index.html", '70c3b169747b60d6f6b9b03461d46d40', "f84c15467d224449fd22f67b127d7754", ""),
  ("docs/bodycare/index.html", 'bfeb9d2201c5f5760969674d988d21b1', "5e67b66095775f53f646ed2a28057163", ""),
  ("docs/site.css", '99ca3c3f99709ac7e749796c805ec4bb', "c8356a4bc49f354adbb82fdfba4362c7", ""),
  ("docs/site.js", 'be4b1e23896ff1ab1e05d8e3177f178a', "9add240f223a48ffec61d76f815ce2fa", ""),
  ("tests/e2e_site_test.py", '644b45a66414a6fce1e5315443ad5eeb', "051a66a2cd73487f3b98dd81708f1688", ""),
  ("tests/e2e_server.ts", 'bd8293475462fe1078e7c0ec9c6d72ce', "8f53d7592741ef95918331cf4b1fb7e7", ""),
  ("README.md", '129a6ddbdb0d591be87c680635f5ccd3', "38221e5d10a560193750a580ff3c9534", ""),
  ("docs/img/icon-180.png", None, "8a73590b79a980481e86d48e29730d25", ""),
  ("docs/img/icon-32.png", None, "29c2961d75e2bc14bd1b7ccef850a49d", ""),
  ("docs/img/icon-512.png", None, "05bdcd536a566287900d061e6d4780e9", ""),
  ("docs/img/logo.png", None, "076b5a6d3c44b11313812bbc38b1ddd2", ""),
  ("docs/img/mark.svg", None, "b78ef548c749d333fc3ed8d7c11de901", ""),
  ("docs/img/wordmark-w.png", None, "607df325bd54bc1c115ad85f937944e0", ""),
  ("docs/img/wordmark.png", None, "b8f82c319ffb03923b466b69c0fea660", ""),
]
REMOVE = {}

def md5(p): return hashlib.md5(open(p, "rb").read()).hexdigest()
if not os.path.exists("docs/config.js") or not os.path.exists("supabase/functions/booking"):
    sys.exit("lifeplus-app のフォルダで流してください")
todo = []
for path, old, new, data in FILES:
    if os.path.exists(path):
        cur = md5(path)
        if cur == new:
            continue
        if old is None or cur != old:
            sys.exit("止めました：%s が思っていた形と違います（md5 %s）。何も変えていません" % (path, cur))
    elif old is not None:
        sys.exit("止めました：%s がありません。何も変えていません" % path)
    todo.append((path, new, data))
gone = []
for path, old in REMOVE.items():
    if os.path.exists(path):
        if md5(path) != old:
            sys.exit("止めました：%s が思っていた形と違います。何も変えていません" % path)
        gone.append(path)
if not todo and not gone:
    print("もう入っています（lifeplus-site-v2）"); sys.exit(0)
for path, new, data in todo:
    b = zlib.decompress(base64.b64decode(data))
    assert hashlib.md5(b).hexdigest() == new
    if os.path.exists(path):
        shutil.copy2(path, path + ".bak_site_v2")
    d = os.path.dirname(path)
    if d:
        os.makedirs(d, exist_ok=True)
    open(path, "wb").write(b)
    assert md5(path) == new
for path in gone:   # 予約ページの部品は docs/yoyaku/ へ移したので、もとの場所からは消す
    shutil.copy2(path, path + ".bak_site_v2")
    os.remove(path)
print("入れました（lifeplus-site-v2）")
